// n8n Code Node
// Mode: Run Once for All Items

const results = [];

for (const item of $input.all()) {

    let data = item.json;

    // ==========================================
    // 1. GET AI TEXT
    // ==========================================

    // Your AI output is:
    // {
    //   "text": "{\"Student_ID\":\"STU1001\", ... }"
    // }

    if (data.text !== undefined) {
        data = data.text;
    }

    // ==========================================
    // 2. PARSE JSON STRING
    // ==========================================

    if (typeof data === "string") {

        let text = data.trim();

        // Remove ```json and ``` if AI adds them
        text = text
            .replace(/^```json\s*/i, "")
            .replace(/^```\s*/i, "")
            .replace(/\s*```$/i, "")
            .trim();

        try {
            data = JSON.parse(text);
        } catch (error) {

            // Try extracting JSON from surrounding text
            const start = text.indexOf("{");
            const end = text.lastIndexOf("}");

            if (start !== -1 && end !== -1) {

                try {
                    data = JSON.parse(
                        text.substring(start, end + 1)
                    );
                } catch (error2) {
                    continue;
                }

            } else {
                continue;
            }
        }
    }

    // ==========================================
    // 3. HANDLE ARRAY OR SINGLE OBJECT
    // ==========================================

    const students = Array.isArray(data)
        ? data
        : [data];

    // ==========================================
    // 4. PROCESS EACH STUDENT
    // ==========================================

    for (const student of students) {

        if (!student || typeof student !== "object") {
            continue;
        }

        // --------------------------------------
        // Student ID
        // --------------------------------------

        const Student_ID = String(
            student.Student_ID ?? ""
        ).trim();


        // --------------------------------------
        // Name
        // --------------------------------------

        const Name = String(
            student.Name ?? ""
        )
        .trim()
        .replace(/\s+/g, " ");


        // --------------------------------------
        // Email
        // --------------------------------------

        const Email = String(
            student.Email ?? ""
        )
        .trim();

        const emailRegex =
            /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

        const Email_Status =
            emailRegex.test(Email)
                ? "Valid"
                : "Invalid";


        // --------------------------------------
        // Phone
        // --------------------------------------

        let Phone = String(
            student.Phone ?? ""
        )
        .trim();

        // Remove spaces, +, -, brackets, etc.
        Phone = Phone.replace(/\D/g, "");

        // Convert +91XXXXXXXXXX → XXXXXXXXXX
        if (
            Phone.length === 12 &&
            Phone.startsWith("91")
        ) {
            Phone = Phone.substring(2);
        }

        const phoneRegex = /^[6-9]\d{9}$/;

        const Phone_Status =
            phoneRegex.test(Phone)
                ? "Valid"
                : "Invalid";


        // --------------------------------------
        // Course
        // --------------------------------------

        const Course = String(
            student.Course ?? ""
        )
        .trim()
        .replace(/\s+/g, " ");


        // --------------------------------------
        // Fee Paid
        // --------------------------------------

        let Fee_Paid = false;

        if (student.Fee_Paid === true) {

            Fee_Paid = true;

        } else if (
            typeof student.Fee_Paid === "string"
        ) {

            const value =
                student.Fee_Paid
                    .trim()
                    .toLowerCase();

            if (
                value === "true" ||
                value === "yes" ||
                value === "paid" ||
                value === "1"
            ) {
                Fee_Paid = true;
            }
        }


        // --------------------------------------
        // City
        // --------------------------------------

        const City = String(
            student.City ?? ""
        )
        .trim()
        .replace(/\s+/g, " ");


        // --------------------------------------
        // Enrolled Date
        // --------------------------------------

        let Enrolled_Date = String(
            student.Enrolled_Date ?? ""
        ).trim();

        if (Enrolled_Date) {

            const date = new Date(Enrolled_Date);

            if (!isNaN(date.getTime())) {

                Enrolled_Date =
                    date.toISOString().split("T")[0];

            } else {

                Enrolled_Date = "";
            }
        }


        // ==========================================
        // 5. FINAL CLEAN OBJECT
        // ==========================================

        results.push({
            json: {
                Student_ID: Student_ID,
                Name: Name,
                Email: Email,
                Email_Status: Email_Status,
                Phone: Phone,
                Phone_Status: Phone_Status,
                Course: Course,
                Fee_Paid: Fee_Paid,
                City: City,
                Enrolled_Date: Enrolled_Date
            }
        });
    }
}

// ==========================================
// 6. RETURN CLEAN ITEMS
// ==========================================

return results;
